<?php $width=max(1,(int)($ad['recommended_width']??970));$height=max(1,(int)($ad['recommended_height']??250));$isSide=$width<=336;$slot=$ad['placement_slug']??''; ?>
<aside class="mag-ad <?=$isSide?'mag-ad--rectangle':'mag-ad--banner'?>" lang="en" data-ad-placement="<?=e($slot)?>" aria-label="Advertisement"><span class="ad-label">Advertisement</span><div class="ad-creative"><?php if($ad['type']==='html'): ?><?=$ad['html_content']?><?php else: ?><a href="<?=e($ad['destination_url']?url($ad['destination_url']):url('/'))?>" target="_blank" rel="sponsored noopener"><img src="<?=e($ad['image_url'])?>" width="<?=$width?>" height="<?=$height?>" alt="<?=e($ad['alt_text'] ?: $ad['name'])?>" loading="<?=in_array($slot,['header','homepage-top','category-top'],true)?'eager':'lazy'?>"></a><?php endif; ?></div></aside>
